package com.personal.meditation;
import android.content.Context;import android.graphics.*;import android.media.ExifInterface;import android.net.Uri;import android.util.AtomicFile;import java.io.*;
/** Decode a picked image into a bounded private JPEG; no external URLs or markup. */
final class BackgroundImage {
 static File file(Context context){return new File(context.getFilesDir(),"meditation-background.jpg");}
 static void importImage(Context context,Uri uri)throws IOException{
  byte[] bytes;try(InputStream in=context.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("No image");byte[] buffer=new byte[16384];for(int n;(n=in.read(buffer))!=-1;){if(out.size()+n>24*1024*1024)throw new IOException("Image is too large");out.write(buffer,0,n);}bytes=out.toByteArray();}
  BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("Unreadable image");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>2048)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("Unreadable image");
  try{int orientation=ExifInterface.ORIENTATION_NORMAL;try{orientation=new ExifInterface(new ByteArrayInputStream(bytes)).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);}catch(IOException ignored){}Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;default:break;}if(!matrix.isIdentity()){Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(rotated!=bitmap){bitmap.recycle();bitmap=rotated;}}AtomicFile target=new AtomicFile(file(context));FileOutputStream out=null;try{out=target.startWrite();if(!bitmap.compress(Bitmap.CompressFormat.JPEG,88,out))throw new IOException("Could not save image");target.finishWrite(out);}catch(IOException|RuntimeException failed){if(out!=null)target.failWrite(out);throw failed;}}finally{bitmap.recycle();}
 }
}
